UPDATE document_chunk
SET chroma_id = CASE document_chunk_id

        WHEN #{c.documentChunkId} THEN #{c.chromaId}

    ELSE chroma_id
    END,
    embedding_model = #{embeddingModel},
    embedding_status = 'COMPLETED',
    updated_at = #{now}
WHERE file_version_id = #{fileVersionId}
  AND document_chunk_id IN

    #{c.documentChunkId}

  AND deleted_at IS NULL
